function count_upper(s: string): int
    reads s
    ensures 0 <= count_upper(s)
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == CountUpper(s[0..i])
    {
        if s[i] >= 'A' && s[i] <= 'Z' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

